using System;using UnityEngine;
namespace FashionFit {
 [DefaultExecutionOrder(210)] public sealed class BodyBoundSurface:MonoBehaviour {
  public ElasticSurface Surface{get;private set;}public double Milliseconds{get;private set;}
  public float MaxSpeed{get;private set;}public int Version{get;private set;}Vector3[] previousPoints;RunwayAvatar avatar;PoseBodyField field;PoseDeformationJob driver;Matrix4x4[] matrices,last;bool first=true;float accumulator;
  static readonly string[] joints={"LeftArm","LeftForeArm","RightArm","RightForeArm","LeftUpLeg","LeftLeg","RightUpLeg","RightLeg","LeftFoot","RightFoot"};
  static readonly string[] tips={"LeftForeArm","LeftHand","RightForeArm","RightHand","LeftLeg","LeftFoot","RightLeg","RightFoot","LeftFoot","RightFoot"};
  Vector3[] neutralA=new Vector3[10],neutralB=new Vector3[10];float[] radii=new float[10];
  public void Initialize(RunwayAvatar body,Mesh mesh,Material material,string gender){avatar=body;gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;gameObject.AddComponent<MeshRenderer>().sharedMaterial=material;Surface=gameObject.AddComponent<ElasticSurface>();Surface.Initialize(MembraneMaterial.Presets[0]);Surface.EnablePoseDriver();gameObject.layer=9;var box=gameObject.AddComponent<BoxCollider>();box.isTrigger=true;box.center=mesh.bounds.center;box.size=mesh.bounds.size+Vector3.one*.04f;gameObject.AddComponent<RunwayVRGrabTarget>().ConfigureElastic(Surface);matrices=new Matrix4x4[body.Bones.Length];last=new Matrix4x4[matrices.Length];field=new PoseBodyField(gender);var bw=mesh.boneWeights;var faces=mesh.triangles;var binding=new BoneWeight[bw.Length+faces.Length/3];Array.Copy(bw,binding,bw.Length);for(int i=0;i<faces.Length;i+=3)binding[bw.Length+i/3]=FittedGarmentGeometry.Average(bw[faces[i]],bw[faces[i+1]],bw[faces[i+2]]);driver=new PoseDeformationJob(mesh.vertices,binding,faces,matrices.Length,field);
   var bodyWeights=body.BodyMesh.boneWeights;for(int k=0;k<10;k++){neutralA[k]=FittedGarmentGeometry.Neutral(body,joints[k]);neutralB[k]=k>=8?neutralA[k]+new Vector3(0,-.04f,.13f):FittedGarmentGeometry.Neutral(body,tips[k]);radii[k]=.025f;int bone=body.BoneIndex(joints[k]);Vector3 line=neutralB[k]-neutralA[k];for(int i=0;i<body.BodyVertices.Length;i++){var w=bodyWeights[i];float own=(w.boneIndex0==bone?w.weight0:0)+(w.boneIndex1==bone?w.weight1:0);if(own<.60f)continue;float u=Vector3.Dot(body.BodyVertices[i]-neutralA[k],line)/Mathf.Max(.00001f,line.sqrMagnitude);if(u>.08f&&u<.92f)radii[k]=Mathf.Max(radii[k],Vector3.Distance(body.BodyVertices[i],neutralA[k]+line*u));}radii[k]+=.018f;}Step(1f/60);var app=body.GetComponentInParent<FashionFitApp>();if(app)ContactGarment.Attach(app,Surface);
  }
  void LateUpdate(){accumulator+=Time.deltaTime;if((Surface&&Surface.GrabCount>0)||accumulator>=1f/30){Step(Mathf.Min(.05f,accumulator));accumulator=0;}}
  public void Step(float dt){if(driver==null)return;avatar.FillSkinMatrices(matrices);bool changed=first;for(int i=0;i<matrices.Length&&!changed;i++)for(int j=0;j<16;j++)if(Mathf.Abs(matrices[i][j]-last[i][j])>1e-5f){changed=true;break;}Milliseconds=0;if(!changed&&Surface.ContactMotion&&Surface.ContactMotion.Active)return;if(!changed&&!Surface.NeedsUpdate)return;var timer=System.Diagnostics.Stopwatch.StartNew();if(changed){for(int k=0;k<10;k++){int bone=avatar.BoneIndex(joints[k]);Vector3 a=matrices[bone].MultiplyPoint3x4(neutralA[k]),b=matrices[bone].MultiplyPoint3x4(neutralB[k]);bool moved=(a-neutralA[k]).sqrMagnitude>.0001f||(b-neutralB[k]).sqrMagnitude>.0001f;driver.SetCapsule(k,a,b,moved?radii[k]:0,bone);}Array.Copy(matrices,last,matrices.Length);first=false;}driver.Run(matrices,Surface,dt,changed,avatar.transform.InverseTransformVector(Physics.gravity),avatar.BodyMesh.bounds.max.y*.60f);var box=GetComponent<BoxCollider>();box.center=Surface.MeshAt(0).bounds.center;box.size=Surface.MeshAt(0).bounds.size+Vector3.one*.04f;var output=Surface.CurrentPoints;if(previousPoints==null)previousPoints=(Vector3[])output.Clone();MaxSpeed=0;for(int i=0;i<output.Length;i++){MaxSpeed=Mathf.Max(MaxSpeed,Vector3.Distance(output[i],previousPoints[i])/Mathf.Max(.001f,dt));previousPoints[i]=output[i];}Version++;Milliseconds=timer.Elapsed.TotalMilliseconds;}
  void OnDestroy(){if(driver!=null)driver.Dispose();if(field!=null)field.Dispose();}
 }
}
